final class CM91_Content_Bridge {
 const NS='cm91-content/v1', SRC='_cm91_content_source_id', COMMIT='_cm91_content_commit', IMAGES='_cm91_content_images', MEDIA_SHA='_cm91_content_media_sha256', LAST='cm91_content_bridge_last_import'; const MAX=52428800, VERSION='0.1.1';
 public static function init(){add_action('rest_api_init',[__CLASS__,'routes']);add_action('admin_menu',[__CLASS__,'menu']);add_action('add_meta_boxes',[__CLASS__,'boxes']);add_action('admin_post_cm91_content_image_zip',[__CLASS__,'image_zip']);add_action('admin_notices',[__CLASS__,'notices']);}
 public static function routes(){register_rest_route(self::NS,'/import',['methods'=>'POST','callback'=>[__CLASS__,'import'],'permission_callback'=>'__return_true']);register_rest_route(self::NS,'/health',['methods'=>'GET','callback'=>fn()=>['ok'=>true,'version'=>self::VERSION,'draft_only'=>true,'non_draft_updates_blocked'=>true,'source_id_only_matching'=>true,'image_zip'=>true,'yoast_meta'=>true,'safe_zip_paths'=>true],'permission_callback'=>'__return_true']);}
 private static function secret(){if(defined('CM91_CONTENT_SECRET')&&CM91_CONTENT_SECRET)return(string)CM91_CONTENT_SECRET;if(defined('CM91_DEPLOY_SECRET')&&CM91_DEPLOY_SECRET)return(string)CM91_DEPLOY_SECRET;return(string)get_option('cm91_git_deployer_secret','');}
 private static function sig($tmp,$r){$s=self::secret();if($s==='')return new WP_Error('cm91_content_not_configured','Content bridge secret is not configured.',['status'=>503]);$got=(string)$r->get_header('x-cm91-deploy-signature');$exp='sha256='.hash_hmac('sha256',file_get_contents($tmp),$s);return($got&&hash_equals($exp,$got))?true:new WP_Error('cm91_content_bad_signature','Invalid content signature.',['status'=>401]);}
 private static function safe_path($n){$n=str_replace('\\','/',(string)$n);return !($n===''||str_starts_with($n,'/')||preg_match('#(^|/)\.\.(/|$)#',$n)||strpos($n,"\0")!==false);}
 private static function author($v){$v=trim((string)$v);if($v==='')return 0;$u=get_user_by('login',$v);if(!$u)$u=get_user_by('slug',sanitize_title($v));if(!$u&&is_email($v))$u=get_user_by('email',$v);return$u?(int)$u->ID:0;}
 private static function manifest($m){$raw=(string)($m['source_id']??'');$src=sanitize_key($raw);$title=sanitize_text_field($m['title']??'');if(!$src||!$title)return new WP_Error('cm91_manifest_required','source_id and title are required.');if(!preg_match('/^[a-z0-9_-]+$/',$raw)||$src!==$raw)return new WP_Error('cm91_manifest_source','Invalid source_id.');if(sanitize_key($m['state']??'draft')!=='draft')return new WP_Error('cm91_manifest_state','Only state=draft is accepted.');if(!empty($m['post_status'])&&sanitize_key($m['post_status'])!=='draft')return new WP_Error('cm91_manifest_status','post_status may only be draft.');$seen=[];foreach(($m['images']??[])as$i){$f=(string)($i['file']??'');if($f===''||basename($f)!==$f||!preg_match('/\.(jpe?g|png|gif|webp)$/i',$f))return new WP_Error('cm91_manifest_image','Invalid image filename.');if(isset($seen[$f]))return new WP_Error('cm91_manifest_duplicate_image','Duplicate image filename.');$seen[$f]=1;}return true;}
 public static function boxes(){foreach(get_post_types(['show_ui'=>true],'names')as$pt)add_meta_box('cm91-content-images','CM91 Bilder importieren',[__CLASS__,'box'],$pt,'side','high');}
 public static function box($p){$src=get_post_meta($p->ID,self::SRC,true);if(!$src){echo'<p>Kein CM91-Git-Import.</p>';return;}if($p->post_status!=='draft'){echo'<p><strong>Geschützt:</strong> Bild-Import ist nur für Entwürfe erlaubt.</p>';return;}$imgs=get_post_meta($p->ID,self::IMAGES,true);if(!is_array($imgs))$imgs=[];$missing=[];foreach($imgs as$i){$f=sanitize_file_name($i['file']??'');if($f&&strpos($p->post_content,'{{image:'.$f.'}}')!==false)$missing[]=$f;}echo'<p><strong>Quelle:</strong><br><code>'.esc_html($src).'</code></p>';echo$missing?'<p><strong>Bilder fehlen: '.count($missing).'</strong><br>'.esc_html(implode(', ',$missing)).'</p>':'<p>✓ Keine offenen Bild-Platzhalter.</p>';$nonce=wp_create_nonce('cm91_content_image_zip_'.$p->ID);echo'<div id="cm91-image-upload"><input type="file" id="cm91-image-zip" accept=".zip,application/zip" style="max-width:100%"><p><button type="button" class="button button-primary" id="cm91-image-submit">Bilder-ZIP hochladen</button></p><p id="cm91-image-status" class="description" aria-live="polite"></p></div>';echo'<script>(function(){var b=document.getElementById("cm91-image-submit"),i=document.getElementById("cm91-image-zip"),s=document.getElementById("cm91-image-status");if(!b||!i)return;b.addEventListener("click",function(e){e.preventDefault();e.stopPropagation();if(!i.files||!i.files.length){s.textContent="Bitte zuerst ein ZIP auswählen.";return;}b.disabled=true;s.textContent="ZIP wird hochgeladen …";var f=document.createElement("form");f.method="post";f.enctype="multipart/form-data";f.action="'.esc_js(admin_url('admin-post.php')).'";f.style.display="none";function h(n,v){var x=document.createElement("input");x.type="hidden";x.name=n;x.value=v;f.appendChild(x);}h("action","cm91_content_image_zip");h("post_id","'.(int)$p->ID.'");h("_wpnonce","'.esc_js($nonce).'");i.name="image_zip";f.appendChild(i);document.body.appendChild(f);f.submit();});})();</script>';}
 public static function notices(){if(!isset($_GET['cm91_images']))return;$n=absint($_GET['cm91_images']);$e=absint($_GET['cm91_errors']??0);echo'<div class="notice '.($e?'notice-warning':'notice-success').' is-dismissible"><p><strong>CM91 Content Bridge:</strong> '.$n.' Bild(er) importiert'.($e?', '.$e.' Fehler':'').'.</p></div>';}
 private static function block($id,$url,$alt){$id=(int)$id;return"\n<!-- wp:image {\"id\":{$id},\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"".esc_url($url)."\" alt=\"".esc_attr($alt)."\" class=\"wp-image-{$id}\" /></figure>\n<!-- /wp:image -->\n";}
 public static function image_zip(){$id=absint($_POST['post_id']??0);if(!current_user_can('upload_files'))wp_die('Keine Berechtigung.');check_admin_referer('cm91_content_image_zip_'.$id);$p=get_post($id);if(!$p)wp_die('Beitrag nicht gefunden.');if(!get_post_meta($id,self::SRC,true))wp_die('Kein CM91-Git-Beitrag.');if($p->post_status!=='draft')wp_die('Nur Entwürfe dürfen verändert werden.');$imgs=get_post_meta($id,self::IMAGES,true);if(!is_array($imgs)||!$imgs)wp_die('Keine Bilder definiert.');if(empty($_FILES['image_zip']['tmp_name'])||!is_uploaded_file($_FILES['image_zip']['tmp_name']))wp_die('Kein ZIP empfangen.');if((int)($_FILES['image_zip']['size']??0)>self::MAX)wp_die('ZIP zu groß.');if(!class_exists('ZipArchive'))wp_die('ZipArchive fehlt.');$expected=[];foreach($imgs as$i){$f=sanitize_file_name($i['file']??'');if($f)$expected[$f]=$i;}$z=new ZipArchive();if($z->open($_FILES['image_zip']['tmp_name'])!==true)wp_die('Ungültiges ZIP.');$found=[];for($i=0;$i<$z->numFiles;$i++){$raw=(string)$z->getNameIndex($i);if(!self::safe_path($raw)){$z->close();wp_die('Unsicherer ZIP-Pfad.');}$raw=str_replace('\\','/',$raw);if(substr($raw,-1)==='/')continue;$f=sanitize_file_name(basename($raw));if(!isset($expected[$f]))continue;$d=$z->getFromIndex($i);if($d===false)continue;$tmp=wp_tempnam($f);if(@file_put_contents($tmp,$d)!==false)$found[$f]=$tmp;}$z->close();if(!$found)wp_die('Kein erwartetes Bild gefunden.');$content=$p->post_content;$featured=0;$done=[];$err=[];foreach($expected as$f=>$meta){if(empty($found[$f]))continue;$aid=self::media($found[$f],$id,sanitize_text_field($meta['alt']??''),sanitize_text_field($meta['title']??''),$f);@unlink($found[$f]);if(is_wp_error($aid)){$err[]=$f;continue;}$url=wp_get_attachment_url($aid);$ph='{{image:'.$f.'}}';if($url&&strpos($content,$ph)!==false)$content=str_replace($ph,self::block($aid,$url,$meta['alt']??''),$content);if(!empty($meta['featured']))$featured=(int)$aid;$done[]=$f;}wp_update_post(['ID'=>$id,'post_content'=>$content]);if($featured)set_post_thumbnail($id,$featured);wp_safe_redirect(add_query_arg(['post'=>$id,'action'=>'edit','cm91_images'=>count($done),'cm91_errors'=>count($err)],admin_url('post.php')));exit;}
 public static function import(WP_REST_Request $r){$f=$r->get_file_params();if(empty($f['package']['tmp_name'])||!is_uploaded_file($f['package']['tmp_name']))return new WP_Error('cm91_content_missing','No content package received.',['status'=>400]);$tmp=$f['package']['tmp_name'];$ok=self::sig($tmp,$r);if(is_wp_error($ok))return$ok;if(!class_exists('ZipArchive'))return new WP_Error('cm91_zip_missing','ZipArchive missing.',['status'=>500]);$stage=trailingslashit(get_temp_dir()).'cm91-content-'.wp_generate_password(12,false,false).'/';wp_mkdir_p($stage);$z=new ZipArchive();if($z->open($tmp)!==true){self::rm($stage);return new WP_Error('cm91_bad_zip','Invalid ZIP.',['status'=>400]);}for($i=0;$i<$z->numFiles;$i++)if(!self::safe_path($z->getNameIndex($i))){$z->close();self::rm($stage);return new WP_Error('cm91_unsafe_zip','Unsafe path in package.',['status'=>400]);}if(!$z->extractTo($stage)){$z->close();self::rm($stage);return new WP_Error('cm91_extract_failed','Extraction failed.',['status'=>500]);}$z->close();$packages=glob($stage.'*/manifest.json')?:[];if(is_file($stage.'manifest.json'))$packages[]=$stage.'manifest.json';$results=[];$errors=[];foreach(array_unique($packages)as$mf){$dir=dirname($mf).'/';$af=$dir.'article.html';if(!is_file($af))continue;$m=json_decode(file_get_contents($mf),true);if(!is_array($m)){$errors[]=['stage'=>'manifest','message'=>'Invalid JSON'];continue;}$valid=self::manifest($m);if(is_wp_error($valid)){$errors[]=['source_id'=>sanitize_key($m['source_id']??''),'stage'=>'manifest','message'=>$valid->get_error_message()];continue;}$src=sanitize_key($m['source_id']);$pt=sanitize_key($m['post_type']??'post');if(!post_type_exists($pt))$pt='post';$av=sanitize_text_field($m['author']??'');$author=self::author($av);if($av!==''&&!$author){$errors[]=['source_id'=>$src,'stage'=>'author','message'=>'Author not found'];continue;}$existing=get_posts(['post_type'=>'any','post_status'=>'any','meta_key'=>self::SRC,'meta_value'=>$src,'numberposts'=>2,'fields'=>'ids']);if(count($existing)>1){$errors[]=['source_id'=>$src,'stage'=>'duplicate_source','message'=>'Duplicate source_id in WordPress; blocked.'];continue;}$payload=['post_type'=>$pt,'post_title'=>sanitize_text_field($m['title']),'post_name'=>sanitize_title($m['slug']??$m['title']),'post_excerpt'=>sanitize_textarea_field($m['excerpt']??''),'post_content'=>file_get_contents($af)];if($author)$payload['post_author']=$author;if($existing){$id=(int)$existing[0];$current=get_post($id);if(!$current||$current->post_status!=='draft'){$results[]=['post_id'=>$id,'source_id'=>$src,'status'=>$current?$current->post_status:'unknown','action'=>'skipped_protected_status'];continue;}$payload['ID']=$id;$id=wp_update_post($payload,true);$action='updated_draft';}else{$payload['post_status']='draft';$id=wp_insert_post($payload,true);$action='created_draft';}if(is_wp_error($id)){$errors[]=['source_id'=>$src,'stage'=>'write','message'=>$id->get_error_message()];continue;}update_post_meta($id,self::SRC,$src);update_post_meta($id,self::COMMIT,sanitize_text_field((string)$r->get_header('x-cm91-commit')));update_post_meta($id,self::IMAGES,is_array($m['images']??null)?$m['images']:[]);self::terms($id,'category',$m['categories']??[]);self::terms($id,'post_tag',$m['tags']??[]);self::seo($id,$m);$cur=get_post($id);$results[]=['post_id'=>(int)$id,'source_id'=>$src,'status'=>$cur?$cur->post_status:'unknown','action'=>$action];}self::rm($stage);$resp=['ok'=>empty($errors),'posts'=>$results,'errors'=>$errors];update_option(self::LAST,$resp,false);return new WP_REST_Response($resp,$errors?422:200);}
 private static function terms($id,$tax,$terms){if(!taxonomy_exists($tax)||!is_array($terms))return;$clean=array_values(array_filter(array_map('sanitize_text_field',$terms)));if($clean)wp_set_object_terms($id,$clean,$tax,false);}
 private static function seo($id,$m){$map=['seo_title'=>'_yoast_wpseo_title','meta_description'=>'_yoast_wpseo_metadesc','focus_keyword'=>'_yoast_wpseo_focuskw','canonical'=>'_yoast_wpseo_canonical','og_title'=>'_yoast_wpseo_opengraph-title','og_description'=>'_yoast_wpseo_opengraph-description','twitter_title'=>'_yoast_wpseo_twitter-title','twitter_description'=>'_yoast_wpseo_twitter-description','schema_page_type'=>'_yoast_wpseo_schema_page_type','schema_article_type'=>'_yoast_wpseo_schema_article_type'];foreach($map as$k=>$meta)if(isset($m[$k])&&trim((string)$m[$k])!=='')update_post_meta($id,$meta,in_array($k,['meta_description','og_description','twitter_description'],true)?sanitize_textarea_field($m[$k]):sanitize_text_field($m[$k]));}
 private static function media($path,$id,$alt,$title,$name){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$allowed=['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','gif'=>'image/gif','webp'=>'image/webp'];if(!isset($allowed[$ext]))return new WP_Error('type','Dateityp nicht erlaubt.');$mime=self::mime($path);if($mime!==$allowed[$ext])return new WP_Error('mime','Bildinhalt passt nicht zur Dateiendung.');$sha=hash_file('sha256',$path);$old=get_posts(['post_type'=>'attachment','post_status'=>'inherit','meta_key'=>self::MEDIA_SHA,'meta_value'=>$sha,'numberposts'=>1,'fields'=>'ids']);if($old)return(int)$old[0];$filter=function($m)use($ext,$allowed){$m[$ext]=$allowed[$ext];return$m;};add_filter('upload_mimes',$filter,999);$copy=wp_tempnam($name);copy($path,$copy);$aid=media_handle_sideload(['name'=>$name,'tmp_name'=>$copy,'error'=>0,'size'=>filesize($copy),'type'=>$allowed[$ext]],$id);remove_filter('upload_mimes',$filter,999);if(is_wp_error($aid))return$aid;wp_update_post(['ID'=>$aid,'post_title'=>$title?:pathinfo($name,PATHINFO_FILENAME)]);if($alt!=='')update_post_meta($aid,'_wp_attachment_image_alt',$alt);update_post_meta($aid,self::MEDIA_SHA,$sha);return$aid;}
 private static function mime($p){if(function_exists('finfo_open')){$f=finfo_open(FILEINFO_MIME_TYPE);if($f){$m=finfo_file($f,$p);finfo_close($f);if($m)return strtolower($m);}}$i=@getimagesize($p);return$i['mime']??'';}
 private static function rm($dir){if(!is_dir($dir))return;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as$i)$i->isDir()?@rmdir($i->getPathname()):@unlink($i->getPathname());@rmdir($dir);}
 public static function menu(){add_management_page('CM91 Content Bridge','CM91 Content Bridge','manage_options','cm91-content-bridge',[__CLASS__,'page']);}
 public static function page(){$last=get_option(self::LAST,[]);echo'<div class="wrap"><h1>CM91 Content Bridge '.esc_html(self::VERSION).'</h1><p>Neue Git-Inhalte werden nur als Entwurf angelegt. Bestehende Git-Inhalte werden nur aktualisiert, solange sie weiterhin Entwürfe sind. Veröffentlichung, Planung, Pending, Private und andere Status sind geschützt. Matching erfolgt ausschließlich über source_id.</p>';if($last)echo'<pre style="white-space:pre-wrap">'.esc_html(wp_json_encode($last,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</pre>';echo'</div>';}
}
